    postSi: `යාපනය එළු මස් හොදි යනු උතුරු ශ්‍රී ලංකාවේ ප්‍රකට, සැර සහ රසවත් මස් ව්‍යංජනයකි. බදින ලද යාපන තුනපහ කුඩු සහ පොල්කිරි යොදා සාදන මෙය බත්, ඉඳිආප්ප හෝ පිට්ටු සමඟ පිළිගන්වයි.`,
