    postSi: `මාළු ඇඹුල් තියල් යනු දකුණු ලංකාවෙන් පැවත එන, ගෝරකා සහ ගම්මිරිස් වැඩිපුර යොදා සාදන සාම්ප්‍රදායික වියළි මාළු කරියකි. ගෝරකා මගින් මෙයට සුවිශේෂී ඇඹුල් රසයක් එක් කරන අතර, මෙම කරිය කල් තබා ගැනීමටද උපකාරී වේ.`,
