    postSi: `මාළු ඇඹුල් තියල් යනු දකුණු ලංකාවෙන් පැවත එන සාම්ප්‍රදායික වියළි මාළු ව්‍යංජනයකි. බලයන් හෝ තලපත් මාළු කැබලි, ගොරකා සහ ගම්මිරිස් මිශ්‍රණයක අලේප කර කල් තබා ගත හැකි වන සේ දිය හිඳෙන තෙක් පිසගනු ලැබේ.`,
