    postSi: `බිත්තර කොත්තු යනු කපන ලද ගෝදම්බ රොටී, බිත්තර, එළවළු සහ තුනපහ එකතු කර තැටියක බැද සාදාගන්නා ජනප්‍රිය ශ්‍රී ලාංකික වීදි ආහාරයකි. මෙය සාමාන්‍යයෙන් සැර හොදි සමඟ පිළිගන්වනු ලැබේ.`,
