    postSi: `කේල් මැල්ලුම් යනු සිහින්ව කපාගත් කේල් කොළ, ගාගත් පොල්, රතු ලූනු, අමුමිරිස් සහ කහ කුඩු මුසු කර සාදාගන්නා පෝෂ්‍යදායී ව්‍යාංජනයකි. දෙහි යුෂ ස්වල්පයක් එකතු කර සකස් කරගන්නා මෙය බත් සමඟ ආහාරයට ගනු ලබයි.`,
