    postSi: `ලූනු රයිතා යනු සිහින්ව ලියාගත් රතු ලූනු, මී කිරි හෝ යෝගට් සහ අමුමිරිස් එකතු කර සාදාගන්නා රසවත් සලාදයකි. මෙය බිරියානි, ලම්ප්රේස් හෝ සැර කෑම වර්ග සමඟ ආහාරයට ගැනීමෙන් මිරිස් සැර සමනය කරගැනීමට උපකාරී වේ.`,
