    postSi: `ඩෙවිල්ඩ් ඉස්සන් යනු සැර, පැණි රස සහ ඇඹුල් රසයෙන් යුත් ජනප්‍රිය ශ්‍රී ලාංකික ආහාරයකි. අමු ඉස්සන්, මාළු මිරිස්, ලූනු, තක්කාලි සහ කෑලි මිරිස් එකතු කර සාදාගන්නා මෙය ෆ්‍රයිඩ් රයිස් සමඟ හෝ කෙටි ආහාරයක් ලෙස ලබා ගනී.`,
