    postSi: `ඩෙවිල්ඩ් දැල්ලෝ යනු ශ්‍රී ලංකාවේ බයිට් එකක් ලෙස සහ ෆ්‍රයිඩ් රයිස් සමඟ ආහාරයට ගන්නා ජනප්‍රිය සැර කෑමකි. තෙලෙන් බැදගත් දැල්ලන් කොටස්, මාළු මිරිස්, ළූණු, තක්කාලි සහ මිරිස් කෑලි එකතු කර සෝස් වර්ග සමඟ රසකර සාදා ගනු ලබයි.`,
