    postSi: `ශ්‍රී ලාංකික එළවළු කට්ලට් යනු තැම්බූ අල, කැරට්, ලීක්ස් සහ අමුමිරිස් එකතු කර සාදාගන්නා ජනප්‍රිය කෙටි කෑමකි. මේවා බිත්තර සහ පාන් කුඩු තවරා ගැඹුරු තෙලෙන් බැද තේ වේලාව සඳහා පිළිගන්වනු ලැබේ.`,
